 SELECT jsonb_build_object('signature',format('%I.%I',n.nspname,p.proname)||'('||oidvectortypes(p.proargtypes)||')','oid',p.oid::text,'owner',pg_get_userbyid(p.proowner),'config',p.proconfig,'acl',p.proacl::text,'secdef',p.prosecdef,'volatility',p.provolatile::text,'input_types',p.proargtypes::text,'all_arg_types',p.proallargtypes,'arg_modes',p.proargmodes,'arg_names',p.proargnames,'returns',p.prorettype::regtype::text,'returns_set',p.proretset,'language',(SELECT lanname FROM pg_language WHERE oid=p.prolang),'parallel',p.proparallel::text,'strict',p.proisstrict,'default_count',p.pronargdefaults,'defaults',pg_get_expr(p.proargdefaults,0),'body_md5',md5(p.prosrc),'ddl_md5',md5(pg_get_functiondef(p.oid))) INTO STRICT backend_now FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.oid=(backend_pin->>'oid')::oid;
 IF backend_now IS DISTINCT FROM backend_pin THEN RAISE EXCEPTION 'CFG8_CURRENT_FULL_ABI_DRIFT';END IF;
 END LOOP;

 IF EXISTS(SELECT 1 FROM public.master_v2_nb_actor_offers_v1 WHERE master_session_id='97d2a684-956d-57ad-8d84-aca627dd9e5c'::uuid) OR EXISTS(SELECT 1 FROM mission_creation_owner.human_encounters WHERE master_session_id='97d2a684-956d-57ad-8d84-aca627dd9e5c'::uuid) THEN RAISE EXCEPTION 'CFG8_OWN_SCENE_NOT_QUIESCENT';END IF;
 IF NOT EXISTS(SELECT 1 FROM mission_factory_owner.quest_run_sources q WHERE session_id='97d2a684-956d-57ad-8d84-aca627dd9e5c'::uuid AND arc_id='324774d7-ef9d-58a7-9f7d-d18b6c68ea3c'::uuid AND control_version=3 AND source_sha256='9dc80ff40032878dbad45f933b2e0469e6d0f3d55c7f8b029e0b5d1f4dc1c61c') THEN RAISE EXCEPTION 'CFG8_OWN_SOURCE_CHANGED';END IF;
 IF ((WITH targets(label,character_id) AS (VALUES ('pg_tamako','f335b077-34a1-41c3-94aa-58ec674b649b'::uuid),('master_riuji','6bceee99-974f-426b-8d92-38b43b4a4267'::uuid)), resources AS (select t.label,c.rank,c.vita,c.vita_max,c.chakra,c.chakra_max,c.exp,c.xp_lifetime,c.money,c.pool_concesso,c.unspent_points,md5(jsonb_build_array(c.taijutsu,c.ninjutsu,c.genjutsu,c.forza,c.velocita,c.mente,c.resistenza,c.fuuinjutsu,c.kekkei_genkai,c.lealta,c.via,c.fama,c.slot_extra)::text) stats_md5,(select count(*) from public.character_inventory x where x.character_id=c.id) inventory_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.item_id,x.quantity,x.created_at) order by x.id),'[]'::jsonb)::text) from public.character_inventory x where x.character_id=c.id) inventory_md5,(select count(*) from public.lesson_progress x where x.user_id=c.user_id) lesson_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.lesson_id,x.completed_at) order by x.id),'[]'::jsonb)::text) from public.lesson_progress x where x.user_id=c.user_id) lesson_md5,(select count(*) from public.character_jutsu x where x.user_id=c.user_id) jutsu_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.jutsu_id,x.source,x.learned_at) order by x.id),'[]'::jsonb)::text) from public.character_jutsu x where x.user_id=c.user_id) jutsu_md5,(select count(*) from public.character_abilities x where x.character_id=c.id) ability_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.technique_id,x.state,x.sessions_done,x.started_at,x.activated_at) order by x.id),'[]'::jsonb)::text) from public.character_abilities x where x.character_id=c.id) ability_md5,(select count(*) from public.character_perks x where x.character_id=c.id) perk_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.tipo,x.dettaglio,x.costo,x.grado_tecnica,x.created_at) order by x.id),'[]'::jsonb)::text) from public.character_perks x where x.character_id=c.id) perk_md5,(select count(*) from public.esame_prove x where x.candidate_user=c.user_id and x.stato='aperta') legacy_exam_open,(select count(*) from exam_regia_private.bindings x where x.owner_user=c.user_id and x.state<>'closed') legacy_binding_open,md5(jsonb_build_array(c.clan,c.element,c.element2,c.cercoterio,c.sigillo)::text) identity_build_md5 from targets t join public.characters c on c.id=t.character_id order by t.label) select jsonb_build_object('at',clock_timestamp(),'protected_md5',md5(jsonb_agg(to_jsonb(r) order by label)::text),'rows',count(*),'fields_per_pg',(select count(*) from jsonb_object_keys((select to_jsonb(x)-'label' from resources x limit 1)))) from resources r))->>'protected_md5' IS DISTINCT FROM 'd41adde267a202a8ff4c6c194eb0a09f' THEN RAISE EXCEPTION 'CFG8_PROTECTED_RESOURCES_CHANGED';END IF;
