 rows_now:=jsonb_build_object('c384',(SELECT to_jsonb(hrow) FROM mission_factory_owner.c384_control hrow WHERE singleton),'c395',(SELECT to_jsonb(hrow) FROM mission_factory_owner.c395_control hrow WHERE singleton),'c407',(SELECT to_jsonb(hrow) FROM mission_factory_owner.c407_control hrow WHERE singleton),'c412',(SELECT to_jsonb(hrow) FROM mission_factory_owner.c412_control hrow WHERE singleton),'c416',(SELECT to_jsonb(hrow) FROM mission_factory_owner.c416_kind_admission hrow WHERE singleton),'c444',(SELECT to_jsonb(hrow) FROM mission_factory_owner.c444_runtime_control hrow WHERE singleton),'c463',(SELECT to_jsonb(hrow) FROM mission_factory_owner.c463_optin_control hrow WHERE singleton),'c464',(SELECT to_jsonb(hrow) FROM mission_factory_owner.c464_control hrow WHERE singleton),'manual',(SELECT coalesce(jsonb_agg(to_jsonb(hrow) ORDER BY actor_user,release_sha256),'[]'::jsonb) FROM mission_factory_owner.manual_authoring_admissions_v1 hrow),'provider_admissions',(SELECT coalesce(jsonb_agg(to_jsonb(hrow) ORDER BY actor_user,release_sha256),'[]'::jsonb) FROM mission_factory_owner.provider_authoring_admissions hrow));
 IF jsonb_build_object('public_authoring_gate',(SELECT jsonb_build_object('enabled',enabled,'release_sha256',release_sha256,'provider_enabled',provider_enabled) FROM mission_public_owner.public_authoring_gate_v1 WHERE singleton),'fixed_gates',(SELECT jsonb_build_object('staff_enabled',staff_enabled,'public_enabled',public_enabled,'public_staff_enabled',public_staff_enabled,'scheduler_staff_enabled',scheduler_staff_enabled,'scheduler_public_enabled',scheduler_public_enabled) FROM mission_factory_owner.quest_fixed30_admission WHERE singleton)) IS DISTINCT FROM public_before THEN RAISE EXCEPTION 'HUMAN_CFG_PUBLIC_SCOPE_CHANGED'; END IF;
 immutable_after:=jsonb_build_object('c384',(rows_now->'c384'),'c395',(rows_now->'c395'),'c407',(rows_now->'c407'),'c412',(rows_now->'c412'),'old_manual',(SELECT jsonb_agg(to_jsonb(hrow) ORDER BY actor_user,release_sha256) FROM mission_factory_owner.manual_authoring_admissions_v1 hrow WHERE release_sha256<>'37dac90525b249f53fc0404b50adb4ed92df0123649326c99260bf656119d806'),'c464',(rows_now->'c464'),'provider',(rows_now->'provider_admissions'),'readiness',(SELECT to_jsonb(hrow) FROM mission_factory_owner.editor_release_readiness hrow WHERE singleton));
 IF immutable_after IS DISTINCT FROM immutable_before THEN RAISE EXCEPTION 'HUMAN_CFG_SHARED_STATE_CHANGED';END IF;
 IF ((rows_now->'c416')-'bound_at'-'expires_at') IS DISTINCT FROM ((expected->'c416')-'bound_at'-'expires_at') OR ((rows_now->'c444')-'bound_at'-'expires_at') IS DISTINCT FROM ((expected->'c444')-'bound_at'-'expires_at') OR ((rows_now->'c463')-'bound_at'-'expires_at') IS DISTINCT FROM ((expected->'c463')-'bound_at'-'expires_at') THEN RAISE EXCEPTION 'CFG8_SEMANTIC_ROW_CHANGED';END IF;
 IF NOT mission_factory_owner.c444_enabled_v1() OR NOT mission_factory_owner.c416_kind_live_v1() THEN RAISE EXCEPTION 'HUMAN_CFG_POSTCONDITION';END IF;
END $human_cfg$;
